export class SearchNotesResponder {
  apply({
    query,
    noteNameMatches,
    memoMatches,
    checkItemMatches,
  }: SearchResults): SearchResult[] {
    const results: SearchResult[] = [];

    for (const row of noteNameMatches) {
      results.push({
        noteId: row.noteId,
        noteName: row.noteName,
        isMemo: row.isMemo,
        matchType: 'note_name',
        ...extractContext(row.noteName, query),
      });
    }

    for (const row of memoMatches) {
      results.push({
        noteId: row.noteId,
        noteName: row.noteName,
        isMemo: true,
        matchType: 'memo_content',
        ...extractContext(row.description, query),
      });
    }

    for (const row of checkItemMatches) {
      const snippet = descriptionSnippet(row.checkItemDescription);
      results.push({
        noteId: row.noteId,
        noteName: row.noteName,
        isMemo: false,
        matchType: 'check_item',
        ...extractContext(row.checkItemName, query),
        checkItemId: row.checkItemId,
        checkItemStatus: row.checkItemStatus,
        checkItemDescriptionSnippet: snippet,

